() => {
  const cookies = document.cookie;
  const ls = {};
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (/auth|token|session|user|sso/i.test(k)) ls[k] = String(localStorage.getItem(k)).slice(0, 100);
    }
  } catch (e) { ls.error = String(e); }
  return { cookie: cookies.slice(0, 500), localStorageKeys: Object.keys(localStorage), authLike: ls };
}

